// Sun position (the SunCalc formulas) and local-time helpers for the 3D view.

const rad = Math.PI / 180;

export interface SunPos {
  /** Elevation above the horizon, radians. */
  alt: number;
  /** Compass bearing toward the sun, radians clockwise from north. */
  bearing: number;
}

export function sunPosition(date: Date, lat: number, lng: number): SunPos {
  const d = date.valueOf() / 86_400_000 - 0.5 + 2_440_588 - 2_451_545;
  const M = rad * (357.5291 + 0.98560028 * d);
  const C = rad * (1.9148 * Math.sin(M) + 0.02 * Math.sin(2 * M) + 0.0003 * Math.sin(3 * M));
  const L = M + C + rad * 102.9372 + Math.PI;
  const e = rad * 23.4397;
  const dec = Math.asin(Math.sin(e) * Math.sin(L));
  const ra = Math.atan2(Math.sin(L) * Math.cos(e), Math.cos(L));
  const H = rad * (280.16 + 360.9856235 * d) + rad * lng - ra;
  const phi = rad * lat;
  const alt = Math.asin(
    Math.sin(phi) * Math.sin(dec) + Math.cos(phi) * Math.cos(dec) * Math.cos(H),
  );
  const az = Math.atan2(Math.sin(H), Math.cos(H) * Math.sin(phi) - Math.tan(dec) * Math.cos(phi));
  return { alt, bearing: (az + Math.PI) % (2 * Math.PI) };
}

function tzOffset(t: number, tz: string): number {
  const p = Object.fromEntries(
    new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    })
      .formatToParts(t)
      .map((x) => [x.type, x.value]),
  );
  return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - t;
}

/** The instant that is `minutes` after local midnight on `ymd` (YYYY-MM-DD) in `tz`. */
export function zonedTime(ymd: string, minutes: number, tz: string): Date {
  const [y, m, d] = ymd.split('-').map(Number);
  const guess = Date.UTC(y, m - 1, d, 0, minutes);
  return new Date(guess - tzOffset(guess - tzOffset(guess, tz), tz));
}

/** Today's date (YYYY-MM-DD) in `tz`. */
export function localYmd(date: Date, tz: string): string {
  return new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(date);
}

// ---------- shade tracing against the LiDAR obstacle grid ----------
const samples = data.courts.map((f) => {
  const out: [number, number][] = [];
  for (let a = -f.pl / 2 + 0.6; a <= f.pl / 2; a += 1.4)
    for (let b = -f.pw / 2 + 0.5; b <= f.pw / 2; b += 1.4) out.push(fromFrame(f, a, b));
  return out;
});
const traced = (s: SunPos): number => {
  const ex = Math.sin(s.bearing);
  const ny = Math.cos(s.bearing);
  const rise = Math.tan(s.alt);
  let shaded = 0;
  let n = 0;
  data.courts.forEach((f, ci) => {
    const h0 = f.z + 1;
    const maxD = Math.min(R * 1.5, (maxTop - h0) / rise);
    for (const [px0, py0] of samples[ci]) {
      n++;
      for (let d = 0.5; d < maxD; d += 0.5) {
        const c = cellOf(px0 + ex * d, py0 + ny * d);
        if (c < 0) break;
        if (topDm[c] !== -32768 && topDm[c] / 10 > h0 + d * rise) {
          shaded++;
          break;
        }
      }
    }
  });
  return n ? shaded / n : 0;
};

// Given helpers: court frame -> world, and obstacle-grid cell lookup.

export const deg = Math.PI / 180;

/** Court-local (a along the length, b across) -> world [x, y]. */
export function fromFrame(f, a, b) {
  return [
    f.cx + Math.cos(f.theta) * a - Math.sin(f.theta) * b,
    f.cy + Math.sin(f.theta) * a + Math.cos(f.theta) * b,
  ];
}

/** Obstacle-grid cell index for a world point, or -1 outside the grid. */
export function cellOf(scene, x, y) {
  const i = Math.floor((x + scene.radius) / scene.cell);
  const j = Math.floor((scene.radius - y) / scene.cell);
  if (i < 0 || j < 0 || i >= scene.g || j >= scene.g) return -1;
  return j * scene.g + i;
}

